from pathlib import Path
R=Path(__file__).resolve().parents[1];p=R/'public/testing-next.html';s=p.read_text()
css='''#free-book-dialog{border:1px solid #dce1d4;border-radius:10px;padding:24px;width:min(92vw,480px);max-height:90vh;overflow:auto;color:#29352d;background:white}#free-book-dialog::backdrop{background:#17201599}#free-book-dialog h2{font:400 31px/1.15 OPortalsBook,Georgia,serif;margin:12px 0}#free-book-dialog p{font-size:13px;line-height:1.5}#free-book-dialog label{display:block;font-size:13px;margin:13px 0 6px}#free-book-dialog input[type=email]{width:100%;font:16px Arial,sans-serif;padding:12px;border:1px solid #aeb89f;border-radius:5px}#free-book-dialog label.free-updates{display:flex;align-items:start;gap:8px;font-size:12px;line-height:1.5;margin:14px 0}#free-book-dialog .free-updates input{margin-top:3px;flex-shrink:0}#free-book-dialog button[type=submit],#free-book-download{display:inline-block;border:0;border-radius:5px;padding:12px 15px;font-weight:700;cursor:pointer}#free-book-dialog .free-notice{font-size:11px;color:#626975}#free-book-feedback{font-size:13px}#free-book-close{float:right;border:0;background:#f1f3ec;color:#52603c;padding:8px;border-radius:4px;cursor:pointer}#free-book-dialog button[disabled]{opacity:.6;cursor:wait}
'''
s=s.replace('</style>',css+'</style>',1)
markup='''<dialog id="free-book-dialog" aria-labelledby="free-book-title"><button type="button" id="free-book-close" aria-label="Close free-book download">Close ×</button><span class="eyebrow">Your free illustrated PDF</span><h2 id="free-book-title">One small idea.<br>A different way to see your day.</h2><p>Enter your email to unlock the SneakPeak Ideas PDF. No account or payment required.</p><form id="free-book-form"><label for="free-book-email">Email address</label><input type="email" id="free-book-email" name="email" autocomplete="email" maxlength="254" required placeholder="you@example.com"><label class="free-updates"><input type="checkbox" id="free-book-updates" name="updates"><span>I’d also like illustrated ideas and book updates by email. <strong>Optional.</strong></span></label><div class="contact-honeypot" aria-hidden="true"><label for="free-book-website">Leave blank</label><input id="free-book-website" name="website" tabindex="-1" autocomplete="off"></div><button type="submit" class="secrets-buy">Unlock my free PDF ↓</button><p class="free-notice">Your download will be available here immediately. We record your email and download request; we do not require newsletter signup or send your address to analytics. <a href="/Testing/info/privacy">Privacy information</a></p></form><p id="free-book-feedback" role="status" aria-live="polite"></p><a class="secrets-buy" id="free-book-download" hidden>Download SneakPeak Ideas ↓</a></dialog>'''
s=s.replace('<dialog id="measurement-dialog"',markup+'<dialog id="measurement-dialog"',1)
s=s.replace('<a data-owner-only hidden href="/Testing/contact-inbox">', '<a data-owner-only hidden href="/Testing/leads">Free-book emails</a><a data-owner-only hidden href="/Testing/contact-inbox">',1)
# Keep online reading free; explain that the PDF asks for an email.
s=s.replace('No subscription required. Updates by email are not available yet.', 'Read online free, or enter your email to download the PDF. Newsletter signup is optional.')
s=s.replace("${b.alwaysFree?'No payment or subscription required'", "${b.alwaysFree?'No payment · Email required for PDF download'")
s=s.replace('<h2>Optional measurement</h2>', '<h2>Free-book email requests</h2><p>On Testing, downloading SneakPeak Ideas requires an email address. We store the address, request date, optional update preference and number of PDF download requests in a private owner list. A signed access cookie keeps the free PDF unlocked for 30 days on this browser; it contains no email address. The PDF is provided here, not sent by email. Checking the optional updates box records interest only: addresses are not yet verified and no automated marketing emails are sent. You can request correction, removal or withdrawal through Contact. Email addresses are never included in analytics.</p><h2>Optional measurement</h2>',1)
js='''
let freeBookUnlocked=false;const freeBookDialog=document.querySelector('#free-book-dialog'),freeBookForm=document.querySelector('#free-book-form'),freeBookFeedback=document.querySelector('#free-book-feedback'),freeBookDownload=document.querySelector('#free-book-download');
function openFreeBook(){if(!freeBookDialog.open)freeBookDialog.showModal();document.querySelector('#free-book-email').focus();}
document.querySelector('#free-book-close').addEventListener('click',()=>freeBookDialog.close());freeBookDialog.addEventListener('click',event=>{if(event.target===freeBookDialog)freeBookDialog.close()});
fetch('/Testing/api/free-book',{credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(data=>{freeBookUnlocked=freeBookUnlocked||data?.allowed===true}).catch(()=>{});
document.addEventListener('click',event=>{const link=event.target.closest('a');if(!link||freeBookUnlocked)return;let url;try{url=new URL(link.href||link.getAttribute('href'),location.origin)}catch{return}if(url.origin===location.origin&&url.pathname==='/Testing/books/sneakpeak-ideas.pdf'){event.preventDefault();event.stopImmediatePropagation();openFreeBook()}},true);
freeBookForm.addEventListener('submit',async event=>{event.preventDefault();const submit=freeBookForm.querySelector('button[type=submit]');submit.disabled=true;freeBookFeedback.textContent='Preparing your free PDF…';try{const response=await fetch('/Testing/api/free-book',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:document.querySelector('#free-book-email').value.trim(),updates:document.querySelector('#free-book-updates').checked,website:document.querySelector('#free-book-website').value})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Please try again.');freeBookUnlocked=true;freeBookForm.hidden=true;freeBookDownload.href=data.download;freeBookDownload.hidden=false;freeBookFeedback.textContent=data.message;freeBookDownload.focus();}catch(error){freeBookFeedback.textContent=error.message||'Please try again.';}finally{submit.disabled=false;}});
if(new URLSearchParams(location.search).get('get')==='1')openFreeBook();
'''
s=s.replace('</script>',js+'</script>',1);p.write_text(s)
print('Added Testing free-PDF email form and owner-list link. No live HTML modified.')
